import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, Timer } from 'claude-code'

import { diskAlerts } from './df'

const alerts = atom({ plugin: 'disk-alert', key: 'alerts' } as const, [] as string[])
const EVERY_MS = 5 * 60_000

async function check($: EngineInterface, paths: string[], threshold: number) {
  try {
    // df exits non-zero when one path is missing but still prints the rest.
    const { stdout } = await $.process.run(['df', '-P', '-h', ...paths])
    const lines = diskAlerts(stdout, threshold)
    await update($, alerts, () => lines)
  } catch {}
}

export const register: Register = (on, options) => {
  const threshold = Number(options.threshold ?? 85)
  const paths = String(options.paths ?? '/,/mnt/c')
    .split(',')
    .map(p => p.trim())
    .filter(Boolean)
  let timer: Timer | undefined

  on('session.start', async ($, e, next) => {
    const started = await next(e)
    timer?.cancel()
    void check($, paths, threshold)
    timer = $.clock.every(EVERY_MS, () => void check($, paths, threshold))
    return started
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const lines = await read($, alerts)
    if (lines.length === 0) return next(e)
    const { Box, Text } = $.ui.resolve(e)
    return (
      <Box flexDirection="column">
        {lines.map(l => (
          <Text key={l} color="warning">
            {l}
          </Text>
        ))}
      </Box>
    )
  })
}

