// Parses `df -P -h` output into one warning line per mount at or above threshold.
export function diskAlerts(stdout: string, threshold: number): string[] {
  const alerts: string[] = []
  for (const line of stdout.trim().split('\n').slice(1)) {
    const [, , , avail, use, ...mount] = line.trim().split(/\s+/)
    const pct = parseInt(use ?? '', 10)
    if (!Number.isNaN(pct) && pct >= threshold) {
      alerts.push(`⚠ ${mount.join(' ')} ${pct}% full (${avail} free)`)
    }
  }
  return alerts
}

